import ctypes
import numpy as np

class GSLMatrix(ctypes.Structure):
    _fields_ = []

def create_gsl_matrix(np_array):
    matrix = GSLMatrix()
    matrix_data = (ctypes.c_double * (np_array.shape[0] * np_array.shape[1]))()
    for i in range(np_array.shape[0]):
        for j in range(np_array.shape[1]):
            matrix_data[i * np_array.shape[1] + j] = np_array[i, j]
    matrix.contents = matrix_data
    return matrix

def copy_matrix(dest, src):
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_matrix_memcpy.argtypes = [ctypes.POINTER(GSLMatrix), ctypes.POINTER(GSLMatrix)]
        gsl.gsl_matrix_memcpy.restype = ctypes.c_int
        if dest.contents.shape[0] != src.contents.shape[0] or dest.contents.shape[1] != src.contents.shape[1]:
            return -1
        result = gsl.gsl_matrix_memcpy(ctypes.byref(dest), ctypes.byref(src))
        return result
    except Exception as e:
        return -1

