    gsl.compute_trial_step.restype = None

    x_ptr = (ctypes.c_double * len(x_data))(*x_data)
    dx_ptr = (ctypes.c_double * len(dx_data))(*dx_data)
    x_trial_ptr = (ctypes.c_double * len(x_trial_data))(*x_trial_data)

