    gsl.gsl_stats_wmean.restype = ctypes.c_double

    # Check if inputs are valid
    if not isinstance(weights, list) or not isinstance(data, list):
        raise TypeError("Inputs must be lists.")

    if len(weights) != len(data):
        raise ValueError("Weights and data lists must have the same length.")

    if len(weights) == 0:
        raise ValueError("Input lists cannot be empty.")

    # Convert lists to ctypes arrays
    n = len(weights)
