import ctypes
import numpy as np

class GSLFunction:
    def __init__(self, func):
        self.func = func

    def __call__(self, x, params):
        return self.func(x)


def my_function(x):
    return np.sin(x)


def integrate_function(func, a, b):
    try:
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except Exception as e:
        print(f"Error loading GSL libraries: {e}")
        return None, None, None

    gsl.gsl_integration_qk61.argtypes = [ctypes.c_void_p, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_double, ctypes.c_void_p]
    gsl.gsl_integration_qk61.restype = ctypes.c_int

    class gsl_function(ctypes.Structure):
        _fields_ = [('f', ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)), ('params', ctypes.c_void_p)]

    gsl_func = gsl_function()
    gsl_func.f = ctypes.CFUNCTYPE(ctypes.c_double, ctypes.c_double)(lambda x: func(x))
    gsl_func.params = ctypes.c_void_p()

    result = ctypes.c_double(0.0)
    error = ctypes.c_double(0.0)
    size = ctypes.c_size_t(0)

    status = gsl.gsl_integration_qk61(ctypes.byref(gsl_func), a, b, ctypes.byref(result), ctypes.byref(error), ctypes.byref(size))

    if status != 0:
        print(f"Integration failed with status {status}")
        return None, None, None

    abs_result = abs(result.value)
    square_result = (func(a) ** 2 + func(b) ** 2) / 2.0

    return result.value, error.value, abs_result, square_result

