import numpy as np

class GSLMatrix:
    def __init__(self, data):
        self.data = np.array(data, dtype=np.float64)
        self.size = self.data.shape[0]
        self.matrix = self.data.ctypes.data_as(ctypes.POINTER(ctypes.POINTER(ctypes.c_double)))

    def is_positive_definite(self):
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_linalg_cholesky_decomp.argtypes = [ctypes.POINTER(ctypes.POINTER(ctypes.c_double)), ctypes.c_int]
        gsl.gsl_linalg_cholesky_decomp.restype = ctypes.c_int

        status = gsl.gsl_linalg_cholesky_decomp(self.matrix, self.size)
        return status == 0

    def cholesky_decomp(self):
        ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        gsl.gsl_linalg_cholesky_decomp.argtypes = [ctypes.POINTER(ctypes.POINTER(ctypes.c_double)), ctypes.c_int]
        gsl.gsl_linalg_cholesky_decomp.restype = ctypes.c_int

        status = gsl.gsl_linalg_cholesky_decomp(self.matrix, self.size)
        if status != 0:
            raise ValueError("Matrix is not positive definite.")

        result = self.data.copy()
        for i in range(self.size):
            for j in range(i + 1, self.size):
                result[i][j] = 0.0
        return result.tolist()

