def wrapped_func(x):
    return test_func(x)

def test_func(x):
    return (x - 2.0) ** 2 + 1.0


def find_minimum(func, x_minimum, x_lower, x_upper):
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    gsl.gsl_function_set_fval.argtypes = [ctypes.POINTER(GSLFunction), ctypes.c_double]
    gsl.gsl_function_set_fval.restype = None

    gsl.gsl_function_set_fval(ctypes.pointer(GSLFunction(func)), 0.0)

    gsl.gsl_root_fsolver_set.argtypes = [ctypes.c_void_p, ctypes.c_void_p, ctypes.c_double, ctypes.c_double]
    gsl.gsl_root_fsolver_set.restype = ctypes.c_int

    solver = gsl.gsl_root_fsolver_alloc(ctypes.c_int(1))
    gsl.gsl_root_fsolver_set(solver, ctypes.pointer(GSLFunction(func)), x_lower, x_upper)

    iter = 0
    max_iter = 100
    status = 0

    while iter < max_iter and status == 0:
        status = gsl.gsl_root_fsolver_iterate(solver)
        x_minimum = gsl.gsl_root_fsolver_root(solver)
        iter += 1

    return x_minimum, func(x_minimum)


